class Solution {
    public String digitSum(String s, int k) {
        while (s.length() > k) {
            StringBuilder nxt = new StringBuilder();
            for (int i = 0; i < s.length(); i += k) {
                int sumVal = 0;
                for (int j = i; j < Math.min(s.length(), i + k); j++) {
                    sumVal += s.charAt(j) - '0';
                }
                nxt.append(sumVal);
            }
            s = nxt.toString();
        }
        return s;
    }
}

