var digitSum = function(s, k) {
    while (s.length > k) {
        let nxt = '';
        for (let i = 0; i < s.length; i += k) {
            let sumVal = 0;
            const end = Math.min(s.length, i + k);
            for (let j = i; j < end; j++) {
                sumVal += Number(s[j]);
            }
            nxt += sumVal.toString();
        }
        s = nxt;
    }
    return s;
};
